const TERMINAL_LABELS={"allow-once":`Allowed once`,"allow-always":`Allowed always`,deny:`Denied`,cancelled:`Cancelled`,applied:`Applied`,"not-applied":`Completion unconfirmed`};function formatApprovalDecisionLabel(e){return TERMINAL_LABELS[e]}function interpretApprovalTerminalOutcome(e,t){if(e.approvalKind!==`system-agent`)return e.decision;if(e.terminalStatus===`cancelled`)return`cancelled`;return e.decision===`deny`&&(t===`denial`||e.applicationStatus===`not-applied`)?`deny`:e.applicationStatus??e.decision}function formatChannelApprovalResolvedLabel(e,t){const n=interpretApprovalTerminalOutcome(e,`application`);return t&&n===e.decision?t(e.decision):TERMINAL_LABELS[n]}function buildSystemAgentApprovalResolvedText(e){const t=interpretApprovalTerminalOutcome(e,`denial`);return t===`cancelled`?`⚠️ OpenClaw change was cancelled because its run ended. No change was made. Retry.`:t===`deny`?`❌ OpenClaw change denied. No change was made.`:t===`applied`?`✅ OpenClaw change approved and applied: ${e.operationSummary}`:t===`not-applied`?`⚠️ OpenClaw change approved, but completion could not be confirmed. Check the current settings before retrying.`:`✅ OpenClaw change approved. Applying: ${e.operationSummary}`}const SYSTEM_AGENT_APPROVAL_EXPIRED_TEXT=`⏱️ OpenClaw change expired. No change was made.`;export{formatChannelApprovalResolvedLabel as i,buildSystemAgentApprovalResolvedText as n,formatApprovalDecisionLabel as r,SYSTEM_AGENT_APPROVAL_EXPIRED_TEXT as t};